    {
      "rank": 1,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine exquisite control of atoms and light with a major advance in precision measurement. They have reshaped timekeeping and opened tests of fundamental physics.",
        "attribution": "Katori and Ye independently developed leading approaches and sustained the experimental programs that established the field.",
        "maturity": "The clocks have been demonstrated repeatedly in independent laboratories and have continued to improve over many years.",
        "uncertainties": [
          "A prize would need to define the contribution narrowly enough to distinguish these clocks from the broader history of optical frequency metrology."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder S. Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The Higgs boson discovery confirmed a central piece of the particle-physics framework and required extraordinary experimental sensitivity and coordination.",
        "attribution": "These leaders helped build and direct ATLAS and CMS, the independent experiments whose combined evidence made the discovery convincing. Credit to a few individuals necessarily represents very large collaborations.",
        "maturity": "The signal has been confirmed and its properties studied across many years of data.",
        "uncertainties": [
          "The scale of the collaborations makes individual attribution difficult, even for major leadership contributions."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Christophe Salomon",
        "John E. Thomas",
        "Martin Zwierlein"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting Fermi gases provide a clean, controllable setting for studying universal quantum many-body behavior, including regimes relevant to superconductivity and nuclear matter.",
        "attribution": "These experimentalists established complementary, influential platforms and measurements. Rudolf Grimm also made major contributions, so the proposed selection cannot capture the full experimental history.",
        "maturity": "The systems have been explored by multiple groups with increasingly precise measurements over decades.",
        "uncertainties": [
          "The broad scope of the field makes it difficult to identify a single discovery and a uniquely bounded set of contributors."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices made controlled quantum many-body systems experimentally accessible, allowing direct study of phenomena that are difficult to calculate or observe in materials.",
        "attribution": "Bloch and Greiner established landmark experimental capabilities, while Zoller developed key theoretical ideas. Cirac's contribution to the theoretical foundations is also substantial.",
        "maturity": "The methods have been reproduced broadly and have generated a sustained body of quantitative results.",
        "uncertainties": [
          "The line between quantum simulation, quantum computation, and broader ultracold-atom physics is not sharply drawn."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Frank Wilczek",
        "Jon Magne Leinaas",
        "Jan Myrheim"
      ],
      "assessment": {
        "nobel_worthiness": "The recognition that two-dimensional particles can have statistics beyond bosons and fermions changed the conceptual possibilities of quantum theory and became central to topological matter.",
        "attribution": "Leinaas and Myrheim gave an early systematic formulation, and Wilczek developed and named the physical concept of anyons. Their contributions are connected but historically distinct.",
        "maturity": "The theoretical framework is established, and later experiments have made anyonic behavior physically consequential.",
        "uncertainties": [
          "The precise scope of a prize would need to distinguish the original theoretical insight from later experimental realizations and applications."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "A nanohertz gravitational-wave background would open a new observational window on massive black-hole systems and the large-scale universe.",
        "attribution": "These researchers have played leading roles in pulsar timing and in building the long observational record needed to identify a common signal.",
        "maturity": "Several timing collaborations have reported evidence consistent with a background, a significant development built from years of observations.",
        "uncertainties": [
          "The signal's interpretation and the relative contributions of candidate sources remain unsettled.",
          "The evidence is newer and less mature than discoveries supported by direct, source-resolved observations."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser was a major advance in semiconductor physics and light generation, enabling compact, tunable sources across important infrared ranges.",
        "attribution": "Cho and Capasso helped establish the design and experimental program, while Faist was central to the first demonstration. The credit is well suited to the listed trio.",
        "maturity": "The device principle has been confirmed, improved, and used widely over several decades.",
        "uncertainties": [
          "Its strongest case is as a transformative technology, and the committee would need to judge how much weight to give that alongside fundamental insight."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical motion brings objects with many degrees of freedom into regimes where quantum behavior can be prepared and measured, bearing directly on the boundary between quantum and classical physics.",
        "attribution": "These researchers led important complementary efforts in mechanical quantum devices and optomechanics.",
        "maturity": "Ground-state preparation and related quantum control have been demonstrated in multiple systems, with the field continuing to develop.",
        "uncertainties": [
          "The candidate groups several achievements and platforms, so the central discovery and its limits are not fully specified."
        ]
      }
    }
  ]
